func (r *systemConnectorRepoGorm) GetByConnectorName(ctx context.Context, connectorName string) (*model.Source, error) {
	var s model.Source
	err := r.db.WithContext(ctx).Where("connector_name = ?", connectorName).First(&s).Error
	notFound := false
	if err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			notFound = true
		} else {
			return nil, err
		}
	}
	var regRow struct {
		EngineType  string `gorm:"column:engine_type"`
		Host        string `gorm:"column:host"`
		Port        int    `gorm:"column:port"`
		DefaultDB   string `gorm:"column:default_database"`
		OptionsJSON string `gorm:"column:options_json"`
	}
	_ = r.db.WithContext(ctx).Raw(`
		SELECT COALESCE(engine_type, '') AS engine_type,
		       COALESCE(host, '') AS host,
		       COALESCE(port, 0) AS port,
		       COALESCE(default_database, '') AS default_database,
		       COALESCE(options_json::text, '') AS options_json
		FROM cdc_system.connection_registry
		WHERE connection_code = ?
		LIMIT 1
	`, connectorName).Scan(&regRow).Error
	if notFound {
		if regRow.OptionsJSON == "" && regRow.Host == "" {
			return nil, nil
		}
		s.ConnectorName = connectorName
		s.SourceType = regRow.EngineType
		s.DatabaseIncludeList = regRow.DefaultDB
	}
	if (s.ServerAddress == "" || strings.Contains(s.ServerAddress, "***")) && regRow.Host != "" {
		if regRow.Port > 0 && !strings.Contains(regRow.Host, "://") {
			s.ServerAddress = regRow.Host + ":" + strconv.Itoa(regRow.Port)
		} else {
			s.ServerAddress = regRow.Host
		}
	}
	if regRow.OptionsJSON != "" && regRow.OptionsJSON != "{}" {
		s.OptionsJSON = []byte(regRow.OptionsJSON)
	}
	return &s, nil
